5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Rekonstruktion Fahrzeugnutzung 2023</title>
7	<style>
8	:root{--fg:#1d1d1f;--muted:#5b5b60;--bg:#fff;--line:#c9c9cf;--head:#eef0f3;--zebra:#f8f9fb;--accent:#8a1c1c}
9	*{box-sizing:border-box}
10	html,body{margin:0;padding:0;background:var(--bg);color:var(--fg)}
11	body{font-family:-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:13px;line-height:1.45;padding:16px}
12	main{max-width:1400px;margin:0 auto;position:relative;z-index:1}
13	h1{font-size:22px;margin:18px 0 6px}
14	h2{font-size:17px;margin:28px 0 8px;padding-bottom:4px;border-bottom:2px solid var(--fg);break-after:avoid}
15	h3{font-size:14px;margin:18px 0 6px;break-after:avoid}
16	p,li{max-width:1100px}
17	.banner{border:3px solid var(--accent);background:#fdf1f1;color:var(--accent);padding:12px 16px;font-weight:700;font-size:15px;text-align:center}
18	.watermark{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:0}
19	.watermark span{transform:rotate(-30deg);font-size:120px;font-weight:800;letter-spacing:12px;color:rgba(138,28,28,.06);white-space:nowrap}
20	.meta{color:var(--muted);font-size:12px}
21	.note{border-left:4px solid #888;background:#f5f5f7;padding:8px 12px;margin:10px 0}
22	.warn{border-left:4px solid #b42318;background:#fdf1f0;padding:8px 12px;margin:10px 0}
23	.tw{overflow-x:auto;margin:6px 0 12px}
24	table{border-collapse:collapse;width:100%;font-size:12px}
25	th,td{border:1px solid var(--line);padding:3px 5px;vertical-align:top;text-align:left}
26	th{background:var(--head);font-weight:600}
27	tbody tr:nth-child(even){background:var(--zebra)}
28	td.n{text-align:right;white-space:nowrap}
29	tr.sum td{font-weight:700;background:#e6e8ec}
30	.b{display:inline-block;border-radius:3px;padding:0 5px;font-size:10.5px;font-weight:700;letter-spacing:.3px;border:1px solid;white-space:nowrap;margin:1px 0}
31	.g{background:#e3f4e6;color:#1d6b2d;border-color:#7cc18b}
32	.bl{background:#e5effc;color:#1a4f9c;border-color:#86aee6}
33	.v{background:#f0e8fb;color:#5b2a9a;border-color:#b79be0}
34	.y{background:#fdf5d6;color:#7a5a00;border-color:#e2c55a}
35	.o{background:#eeeeef;color:#4a4a4f;border-color:#b5b5ba}
36	.r{background:#fde6e4;color:#a1211a;border-color:#ec958d}
37	.legend span{margin-right:10px}
38	.chk{font-size:15px;text-align:center}
39	.sig{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:40px}
40	.sig div{border-top:1px solid var(--fg);padding-top:4px;font-size:12px}
41	.small{font-size:11px;color:var(--muted)}
42	@media (max-width:700px){.sig{grid-template-columns:1fr}.watermark span{font-size:60px}}
43	@page{size:A4 landscape;margin:10mm}
44	@media print{
45	 body{padding:0;font-size:9pt}
46	 table{font-size:7.5pt}
47	 th,td{padding:1.5px 3px}
48	 .tw{overflow:visible}
49	 h2{break-before:auto}
50	 tr{break-inside:avoid}
51	 thead{display:table-header-group}
52	 .watermark span{color:rgba(138,28,28,.08)}
53	 .banner{-webkit-print-color-adjust:exact;print-color-adjust:exact}
54	 .b,th,tr.sum td,.watermark{-webkit-print-color-adjust:exact;print-color-adjust:exact}
55	}
